const teFamilyGuidance: Record<ConditionCategory, string[]> = {
  "Mood & anxiety": ["తక్కువ చేసి మాట్లాడకుండా లేదా నిందించకుండా ప్రశాంతంగా వినండి.","నిద్ర, భోజనం, అపాయింట్‌మెంట్ లేదా రోజువారీ బాధ్యతల్లో ఏ సహాయం ఉపయోగపడుతుందో అడగండి.","బెదిరింపులు లేదా అంతులేని భరోసాతో కాకుండా చికిత్సను ప్రోత్సహించండి.","నిరాశ, ఆవేశం లేదా పెద్ద ప్రవర్తనా మార్పు ఉంటే భద్రత గురించి నేరుగా అడగండి."],
  "Thought & perception": ["అసాధారణ నమ్మకాలపై వాదించకుండా చిన్న, ప్రశాంతమైన వాక్యాలతో మాట్లాడండి.","శబ్దం మరియు గొడవ తగ్గించి ఆహారం, నీరు, నిద్ర మరియు ఫాలో-అప్‌కు సహాయం చేయండి.","నిద్ర, స్వీయ సంరక్షణ, అనుమానం, మాట లేదా మందుల వాడకంలో ప్రారంభ మార్పులను గమనించండి.","వ్యక్తి భద్రంగా ఉండలేకపోతే లేదా తన సంరక్షణ చేసుకోలేకపోతే తక్షణ అంచనా పొందండి."],
  Addiction: ["అవమానం లేకుండా మార్పుకు తోడ్పడుతూ డబ్బు, పదార్థాలు మరియు ప్రమాదకర ప్రవర్తనపై స్పష్టమైన హద్దులు ఉంచండి.","ఓవర్‌డోస్, తీవ్రమైన విత్‌డ్రావల్ లేదా హింసను దాచవద్దు.","వైద్య సలహా లేకుండా ఆల్కహాల్ లేదా సెడేటివ్‌లను ఒక్కసారిగా ఆపమని బలవంతం చేయవద్దు.","కుటుంబ సభ్యుల ఆరోగ్యాన్ని కూడా రక్షించుకుని అవసరమైతే వారికి సహాయం పొందండి."],
  "Sleep & stress": ["స్థిరమైన నిద్రలేచే సమయం, వాస్తవిక పనిభారం మరియు విశ్రాంతికి సహాయం చేయండి.","నిద్రను బలవంతంగా నియంత్రించవద్దు లేదా సూచించని నిద్ర మాత్రలు, ఆల్కహాల్ ఇవ్వవద్దు.","అనుమతితో గురక, శ్వాస ఆగటం, రాత్రి ప్రవర్తన లేదా పగటి నిద్రమత్తు గమనికలను పంచుకోండి.","సమస్య కొనసాగితే లేదా పనితీరు, భద్రత ప్రభావితమైతే అంచనాను ప్రోత్సహించండి."],
  "Memory & ageing": ["పదేపదే సరిదిద్దడం కంటే సులభమైన ఎంపికలు, పరిచిత దినచర్య మరియు గౌరవప్రదమైన గుర్తుచూపులు ఉపయోగించండి.","సమ్మతితో మందులు, అపాయింట్‌మెంట్లు, డబ్బు, డ్రైవింగ్ మరియు ఇంటి భద్రతను గమనించండి.","అకస్మాత్తు గందరగోళం, కొత్త బలహీనత, జ్వరం, ఫిట్స్ లేదా వేగమైన క్షీణతను అత్యవసర మార్పుగా చూడండి.","ఒక్క సంరక్షకుడిపై భారం పడకుండా బాధ్యతలు మరియు విశ్రాంతిని పంచుకోండి."],
  "Children & adolescents": ["ప్రతి కష్టమైన ప్రవర్తనను ఉద్దేశపూర్వక అవిధేయతగా చూడకుండా పిల్ల లేదా యువకుడి మాట వినండి.","వయస్సుకు తగిన స్థిర దినచర్య, స్పష్టమైన అంచనాలు మరియు ప్రశాంత స్పందనలు ఉపయోగించండి.","తగిన సమ్మతి మరియు గోప్యతతోనే పాఠశాల లేదా ఇతర సంరక్షకులతో సమన్వయం చేయండి.","స్వీయహాని, ఓవర్‌డోస్, తీవ్రమైన హింస, సైకోసిస్ లేదా భద్రంగా ఉండలేని పరిస్థితిలో అత్యవసర సహాయం పొందండి."],
  "Life stages & relationships": ["గోప్యత, స్వతంత్రత మరియు సమ్మతిని గౌరవించండి; సహాయం నియంత్రణగా మారకూడదు.","పక్షం తీసుకోకుండా, నిందించకుండా లేదా బలవంతంగా వివరాలు చెప్పించకుండా వినండి.","స్వాగతిస్తే అపాయింట్‌మెంట్లు, విశ్రాంతి, పిల్లల సంరక్షణ లేదా రోజువారీ పనుల్లో సహాయం చేయండి.","హింస, బలవంతం, స్వీయహాని లేదా తక్షణ ప్రమాదంలో వ్యక్తిగత భద్రతా ప్రణాళికకు ప్రాధాన్యం ఇవ్వండి."],
};

export function TeConditionPage({ slug }: { slug: string }) {
  const c=teConditions[slug];const en=conditions.find(x=>x.slug===slug);if(!c||!en)return null;
  const related=en.related.slice(0,4).map(x=>({slug:x,data:teConditions[x]})).filter(x=>x.data);
  const references=getMedicalReferences(slug);
  const faq=[{question:`${c.name}కు చికిత్స ఉందా?`,answer:"చాలా మంది సరైన అవగాహన, ప్రాక్టికల్ మార్పులు, సైకలాజికల్ సహాయం మరియు అవసరమైనప్పుడు మందులతో మెరుగుపడవచ్చు. ప్రతి వ్యక్తి ప్రణాళిక వేరు; బాధ్యతాయుత వైద్యుడు హామీతో నయం చేస్తామని చెప్పరు."},{question:"మందులు జీవితాంతం అవసరమా?",answer:"అవసరం తప్పనిసరి కాదు. వ్యాధి, తీవ్రత, గత ఎపిసోడ్లు మరియు స్పందనపై ఆధారపడుతుంది. మందులను వైద్య సలహా లేకుండా అకస్మాత్తుగా ఆపకండి."},{question:"మొదటి కన్సల్టేషన్‌లో ఏమి జరుగుతుంది?",answer:"లక్షణాల కాలక్రమం, నిద్ర, శారీరక ఆరోగ్యం, మందులు, కుటుంబ పరిస్థితి మరియు భద్రత గురించి డాక్టర్ వింటారు. అంచనా అంటే ఆటోమేటిక్‌గా మందులు కాదు."}];
  return <div lang="te-IN"><MedicalWebPageJsonLd name={c.seoH1 || `${c.name} చికిత్స విజయవాడ`} description={c.seoDescription || c.summary} path={`/te/conditions/${slug}`} about={c.name} dateModified={en.updatedAt} citations={references.map(reference=>reference.href)} language="te-IN"/><TeHero badge={en.category} image={conditionImage(slug)} title={c.seoH1 || `${c.name} చికిత్స విజయవాడ`} description={`${c.name} లక్షణాలు, నిర్ధారణ మరియు చికిత్స ఎంపికలను గౌరవప్రదమైన మానసిక ఆరోగ్య సంరక్షణతో అర్థం చేసుకోండి. ${c.summary}`} current={c.name}><Button asChild><a href="/te/appointment"><CalendarDays/>అపాయింట్‌మెంట్ కోరండి</a></Button><Button asChild variant="outline"><a href="#te-symptoms">లక్షణాలు చూడండి</a></Button></TeHero><div className="container-page pt-8"><ContentAttribution updatedAt={en.updatedAt} language="te"/></div>{c.urgent&&<div className="container-page pt-8"><TeEmergencyStrip/></div>}<section id="te-symptoms" className="container-page py-16 md:py-22"><div className="grid gap-10 lg:grid-cols-[.75fr_1.25fr]"><div><p className="eyebrow">లక్షణాలు</p><h2 className="section-title mt-5">మీరు లేదా కుటుంబం గమనించవచ్చేవి</h2><p className="mt-4 text-sm leading-7 text-muted-foreground">ఒక్క లక్షణంతో నిర్ధారణ చేయలేం. వ్యవధి, తీవ్రత, సందర్భం మరియు పనితీరు ముఖ్యం.</p></div><div className="grid gap-3 sm:grid-cols-2">{c.symptoms.map(x=><div key={x} className="flex gap-3 rounded-2xl border border-border bg-card p-4"><Check className="mt-1 size-4 shrink-0 text-secondary"/><p className="text-sm font-semibold leading-6">{x}</p></div>)}</div></div></section><section className="border-y border-border bg-muted/55 py-16 md:py-22"><div className="container-page grid gap-6 lg:grid-cols-2"><Card className="p-7"><h2 className="text-2xl font-extrabold">సాధారణ కారణాలు మరియు ప్రభావాలు</h2><p className="mt-3 text-sm text-muted-foreground">సాధారణంగా ఒక్క కారణం ఉండదు; ఎవరినీ నిందించాల్సిన అవసరం లేదు.</p><ul className="mt-6 grid gap-3">{c.causes.map(x=><li key={x} className="flex gap-3 text-sm leading-6 text-muted-foreground"><span className="mt-2 size-1.5 shrink-0 rounded-full bg-accent"/>{x}</li>)}</ul></Card><Card className="p-7"><h2 className="text-2xl font-extrabold">ప్రమాద కారకాలు</h2><p className="mt-3 text-sm leading-7 text-muted-foreground">కుటుంబ చరిత్ర, గత ఎపిసోడ్లు, తీవ్రమైన ఒత్తిడి, నిద్రలేమి, శారీరక వ్యాధులు లేదా పదార్థాల వాడకం ప్రమాదాన్ని పెంచవచ్చు. ప్రమాద కారకం ఉన్నంత మాత్రాన సమస్య తప్పనిసరిగా వస్తుందని కాదు.</p><div className="mt-6 flex gap-3 rounded-xl bg-primary/6 p-4"><ShieldCheck className="size-5 shrink-0 text-primary"/><p className="text-sm leading-6 text-muted-foreground">వ్యక్తిగత ఆరోగ్యం, వయస్సు, గర్భధారణ, మందులు మరియు భద్రతను వైద్యుడు ప్రత్యేకంగా పరిగణిస్తారు.</p></div></Card></div></section><section className="container-page py-16 md:py-22"><div className="grid gap-10 lg:grid-cols-2"><div className="rounded-[1.8rem] bg-[#0b3b64] p-7 text-white"><h2 className="text-3xl font-extrabold">నిర్ధారణ ఎలా చేస్తారు?</h2><p className="mt-5 text-sm leading-8 text-slate-200">{c.name} నిర్ధారణలో లక్షణాలు, అవి ఎంతకాలం ఉన్నాయి, రోజువారీ జీవితంపై ప్రభావం, భద్రత, శారీరక ఆరోగ్యం, ప్రస్తుత మందులు మరియు పదార్థాల వాడకాన్ని పరిశీలిస్తారు. అవసరమైనప్పుడు రక్త పరీక్షలు లేదా ఇతర వైద్య రిఫరల్ సూచించవచ్చు.</p></div><div><p className="eyebrow">చికిత్స ఎంపికలు</p><h2 className="section-title mt-5">వ్యక్తికి తగిన ప్రణాళిక</h2><div className="mt-7 grid gap-4">{c.treatments.map((x,i)=><div key={x} className="flex gap-4 rounded-2xl border border-border bg-card p-5"><span className="flex size-9 shrink-0 items-center justify-center rounded-xl bg-primary/8 text-xs font-black text-primary">0{i+1}</span><p className="text-sm font-semibold leading-7">{x}</p></div>)}</div></div></div></section><section className="border-y border-border bg-muted/55 py-16"><div className="container-page grid gap-8 lg:grid-cols-[.72fr_1.28fr]"><div><h2 className="text-3xl font-extrabold">కుటుంబం మరియు సంరక్షకులు ఎలా సహాయం చేయవచ్చు?</h2><p className="mt-4 text-sm leading-7 text-muted-foreground">నింద లేదా బలవంతం కంటే గౌరవం, సమ్మతి మరియు భద్రతను కాపాడే సహాయం ఉపయోగకరం.</p></div><ul className="grid gap-3 sm:grid-cols-2">{teFamilyGuidance[en.category].map(item=><li key={item} className="flex gap-3 rounded-2xl border border-border bg-card p-5 text-sm leading-7 text-muted-foreground"><Check className="mt-1 size-4 shrink-0 text-secondary"/>{item}</li>)}</ul></div></section><section className="border-b border-border bg-card py-16"><div className="container-page grid gap-6 lg:grid-cols-2"><div className="rounded-[1.7rem] bg-muted/55 p-7"><h2 className="text-2xl font-extrabold">సైకియాట్రిస్ట్‌ను ఎప్పుడు సంప్రదించాలి?</h2><ul className="mt-5 grid gap-3 text-sm leading-7 text-muted-foreground"><li>• లక్షణాలు కొనసాగుతున్నప్పుడు లేదా మళ్లీ వస్తున్నప్పుడు</li><li>• నిద్ర, చదువు, పని, సంబంధాలు లేదా స్వీయ సంరక్షణ ప్రభావితమైనప్పుడు</li><li>• ఆల్కహాల్ లేదా ఇతర పదార్థాలపై ఆధారపడుతున్నప్పుడు</li><li>• కుటుంబం భద్రత లేదా ప్రవర్తనా మార్పుపై ఆందోళన చెందుతున్నప్పుడు</li></ul></div><div className="rounded-[1.7rem] border border-secondary/20 bg-secondary/7 p-7"><Sparkles className="size-6 text-secondary"/><h2 className="mt-4 text-2xl font-extrabold">త్వరగా చికిత్స ఎందుకు ముఖ్యం?</h2><p className="mt-4 text-sm leading-7 text-muted-foreground">త్వరగా అంచనా వల్ల వైద్య కారణాలను గుర్తించవచ్చు, రోజువారీ నష్టాన్ని తగ్గించవచ్చు మరియు అవసరమైన కనీస ప్రభావవంతమైన సంరక్షణను ప్రారంభించవచ్చు. పురోగతికి సమయం పట్టవచ్చు; ఆశ మరియు గౌరవం చికిత్సలో భాగం.</p></div></div></section><section className="container-page py-16"><div className="grid gap-10 lg:grid-cols-[.7fr_1.3fr]"><div><p className="eyebrow">తరచుగా అడిగే ప్రశ్నలు</p><h2 className="section-title mt-5">{c.name} గురించి</h2></div><div className="rounded-[1.7rem] border border-border bg-card px-6 shadow-card"><FAQList faqs={faq}/></div></div>{related.length>0&&<div className="mt-12"><h2 className="text-2xl font-extrabold">సంబంధిత పరిస్థితులు</h2><div className="mt-5 flex flex-wrap gap-3">{related.map(x=><a key={x.slug} href={`/te/conditions/${x.slug}`} className="rounded-full border border-border bg-card px-4 py-2 text-sm font-bold hover:text-primary">{x.data.name}</a>)}</div></div>}</section><section className="container-page pb-16"><MedicalReferences references={references} updatedAt={en.updatedAt} language="te"/></section><TeCTA title={`${c.name} మీ భవిష్యత్తును నిర్వచించదు.`}/></div>;
}

export function TeServicesIndex() {
  return <div lang="te"><TeHero badge={`${services.length} సేవలు`} title="అవసరానికి తగిన సేవ—ఒకే విధానం అందరికీ కాదు." description="పూర్తి అంచనాతో ప్రారంభించి, కారణం మరియు లక్ష్యాలతో సరైన సేవను కలిసి ఎంచుకుంటాము." current="సేవలు"><Button asChild><a href="/te/appointment"><CalendarDays/>అపాయింట్‌మెంట్</a></Button></TeHero><section className="container-page py-14 md:py-20"><div className="grid gap-5 md:grid-cols-2">{services.map((s,i)=>{const t=teServices[s.slug];return <a key={s.slug} href={`/te/services/${s.slug}`} className="group rounded-[1.6rem] border border-border bg-card p-6 shadow-card transition hover:-translate-y-1 hover:border-accent/35"><span className="text-xs font-black text-primary">0{i+1}</span><h2 className="mt-3 text-xl font-extrabold group-hover:text-primary">{t.name}</h2><p className="mt-3 text-sm leading-7 text-muted-foreground">{t.short}</p></a>})}</div><div className="mt-8"><TeEmergencyStrip/></div></section><TeCTA/></div>;
}

export function TeServicePage({ slug }: { slug: string }) {
  const s=teServices[slug];const en=services.find(item=>item.slug===slug);if(!s||!en)return null;
  const related=en.relatedConditions.map(conditionSlug=>({slug:conditionSlug,data:teConditions[conditionSlug]})).filter(item=>item.data);
  const faqs=teServiceFaqs[slug]||[];
  return <div lang="te-IN"><LocalServiceJsonLd name={s.name} description={s.short} path={`/te/services/${slug}`} area="విజయవాడ, ఆంధ్రప్రదేశ్" language="te-IN"/><TeHero badge="క్లినికల్ సేవ" image={serviceImage(slug)} title={s.name} description={s.short} current={s.name}><Button asChild><a href="/te/appointment"><CalendarDays/>అపాయింట్‌మెంట్ కోరండి</a></Button></TeHero><section className="container-page py-16 md:py-22"><div className="grid gap-8 lg:grid-cols-2"><Card className="p-7"><h2 className="text-2xl font-extrabold">ఈ సేవలో ఉండేవి</h2><ul className="mt-6 grid gap-4">{s.includes.map(x=><li key={x} className="flex gap-3 text-sm leading-7 text-muted-foreground"><Check className="mt-1 size-4 shrink-0 text-secondary"/>{x}</li>)}</ul></Card><div className="rounded-[1.8rem] bg-[#0b3b64] p-7 text-white"><h2 className="text-2xl font-extrabold">ఎవరికి ఉపయోగపడవచ్చు?</h2><p className="mt-5 text-sm leading-8 text-slate-200">కొత్త మానసిక ఆరోగ్య సమస్య, గత లక్షణాలు తిరిగి రావటం, కుటుంబ మార్గదర్శకం, మందుల సమీక్ష లేదా రోజువారీ పనితీరు తగ్గినప్పుడు ఈ సేవపై సంప్రదించవచ్చు. తగిన సేవను వైద్య అంచనా తర్వాత నిర్ణయిస్తారు.</p><p className="mt-6 border-t border-white/15 pt-5 text-xs leading-6 text-amber-200"><strong>ముఖ్యం:</strong> {s.note}</p></div></div><section className="mt-12"><h2 className="section-title">సేవ ఎలా పనిచేస్తుంది?</h2><div className="mt-7 grid gap-4 md:grid-cols-4">{["అభ్యర్థన పంపండి","క్లినిక్ సమయం నిర్ధారిస్తుంది","అవసరాన్ని అంచనా వేస్తారు","పురోగతిని సమీక్షిస్తారు"].map((x,i)=><div key={x} className="rounded-2xl border border-border bg-card p-5"><span className="text-xs font-black text-primary">0{i+1}</span><p className="mt-3 text-sm font-extrabold">{x}</p></div>)}</div></section><section className="mt-12 grid gap-8 lg:grid-cols-[.72fr_1.28fr]"><div><p className="eyebrow">సంబంధిత గైడ్లు</p><h2 className="mt-5 text-3xl font-extrabold">ఈ సేవకు సంబంధించిన పరిస్థితులు</h2><div className="mt-6 grid gap-3">{related.map(item=><a key={item.slug} href={`/te/conditions/${item.slug}`} className="flex items-center justify-between rounded-xl border border-border bg-card p-4 text-sm font-extrabold shadow-card hover:text-primary">{item.data.name}<ArrowRight className="size-4"/></a>)}</div></div><div><p className="eyebrow">సేవ గురించి ప్రశ్నలు</p><h2 className="mt-5 text-3xl font-extrabold">తరచుగా అడిగే ప్రశ్నలు</h2><div className="mt-6 rounded-[1.7rem] border border-border bg-card px-6 shadow-card"><FAQList faqs={faqs}/></div></div></section><div className="mt-10 rounded-2xl bg-primary/6 p-5 text-sm leading-7 text-muted-foreground"><a href="/te/conditions" className="font-extrabold text-primary underline underline-offset-4">పరిస్థితుల గైడ్లు</a>, <a href="/te/doctor/pamarthi-krishna-das" className="font-extrabold text-primary underline underline-offset-4">డా. పామర్తి కృష్ణ దాస్ వివరాలు</a> మరియు <a href="/te/clinic-vijayawada" className="font-extrabold text-primary underline underline-offset-4">క్లినిక్ సందర్శన సమాచారం</a> చూడండి.</div></section><TeCTA title={`${s.name} మీ అవసరానికి తగినదా అని అడగండి.`}/></div>;
}

export function TeBlogIndex() {
  return <div lang="te"><TeHero badge={`${articles.length} విస్తృత వ్యాసాలు`} title="రోగులు మరియు కుటుంబాల కోసం తెలుగు మానసిక ఆరోగ్య గ్రంథాలయం." description="లక్షణాలు గుర్తించడం, కుటుంబానికి సహాయం చేయడం మరియు ఎప్పుడు వైద్య సహాయం పొందాలో బాధ్యతాయుత సమాచారం." current="వ్యాసాలు"/><section className="container-page py-14 md:py-20"><div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{articles.map(a=>{const t=teArticleMeta[a.slug];return <a key={a.slug} href={`/te/blog/${a.slug}`} className="group overflow-hidden rounded-[1.6rem] border border-border bg-card p-6 shadow-card transition hover:-translate-y-1 hover:border-accent/35"><div className="relative -mx-6 -mt-6 mb-6 aspect-[16/9]"><Image src={articleImage(a.slug)} alt={aiImageAlt(t.title,"te")} fill sizes="(max-width: 768px) 100vw, 33vw" className="object-cover"/></div><BookOpen className="size-5 text-primary"/><h2 className="mt-5 text-xl font-extrabold group-hover:text-primary">{t.title}</h2><p className="mt-3 text-sm leading-7 text-muted-foreground">{t.description}</p><span className="mt-5 inline-flex text-xs font-extrabold text-primary">వ్యాసం చదవండి →</span></a>})}</div></section><TeCTA/></div>;
}

export function TeArticlePage({ slug }: { slug: string }) {
  const localized=teArticleMeta[slug];
  const sections=teArticleSections[slug];
  const source=articles.find(item=>item.slug===slug);
  if(!localized||!sections||!source)return null;
  const teluguUpdatedAt="2026-08-20";
  const updated=new Intl.DateTimeFormat("te-IN",{day:"numeric",month:"long",year:"numeric",timeZone:"UTC"}).format(new Date(`${teluguUpdatedAt}T00:00:00Z`));
  return <div lang="te-IN">
    <ArticleJsonLd article={source} path={`/te/blog/${slug}`} headline={localized.title} description={localized.description} dateModified={teluguUpdatedAt} language="te-IN" includeMedicalReview={false}/>
    <TeHero badge="తెలుగు మానసిక ఆరోగ్య వ్యాసం" image={articleImage(slug)} title={localized.title} description={localized.description} current={localized.title}/>
    <div className="container-page pt-8"><div className="flex flex-wrap gap-x-5 gap-y-2 rounded-2xl border border-border bg-card p-5 text-xs font-bold text-muted-foreground"><span className="inline-flex items-center gap-1.5"><BookOpen className="size-4 text-primary"/>రచన: కృష్ణ న్యూరో సైకియాట్రిక్ సెంటర్ ఎడిటోరియల్ టీమ్</span><span className="inline-flex items-center gap-1.5"><CalendarDays className="size-4 text-primary"/>చివరిగా నవీకరించిన తేదీ: {updated}</span><span>{source.readingMinutes} నిమిషాల పఠనం</span></div></div>
    <article className="container-page grid gap-10 py-14 lg:grid-cols-[minmax(0,1fr)_19rem]"><div><div className="rounded-[1.6rem] border border-primary/15 bg-primary/6 p-6"><h2 className="text-lg font-extrabold">ముఖ్యాంశాలు</h2><ul className="mt-4 grid gap-3">{localized.points.map(x=><li key={x} className="flex gap-3 text-sm leading-7 text-muted-foreground"><Check className="mt-1 size-4 shrink-0 text-secondary"/>{x}</li>)}</ul></div><div className="prose-clinic">{sections.map(section=><section key={section.heading}><h2>{section.heading}</h2>{section.paragraphs.map(paragraph=><p key={paragraph}>{paragraph}</p>)}{section.bullets&&<ul>{section.bullets.map(item=><li key={item}>{item}</li>)}</ul>}</section>)}<h2>ఆధారాలు మరియు మరింత సమాచారం</h2><ul>{source.references.map(reference=><li key={reference.href}><a href={reference.href} target="_blank" rel="noreferrer">{reference.label}<ExternalLink className="ml-1 inline size-3.5"/></a></li>)}</ul><p>ఈ వ్యాసం సాధారణ అవగాహన కోసం మాత్రమే. వ్యక్తిగత నిర్ధారణ, మందులు, వయస్సు, గర్భధారణ, శారీరక ఆరోగ్యం లేదా భద్రతను అంచనా వేయదు.</p></div><div className="mt-10"><TeEmergencyStrip/></div></div><aside className="lg:sticky lg:top-28 lg:self-start"><div className="rounded-[1.6rem] bg-[#0b3b64] p-6 text-white"><MessageCircle className="size-5 text-emerald-300"/><h2 className="mt-4 text-xl font-extrabold">వ్యక్తిగత మార్గదర్శకం కావాలా?</h2><p className="mt-3 text-sm leading-7 text-slate-200">వ్యాసం సమాచారం ఇస్తుంది; కన్సల్టేషన్ మీ వ్యక్తిగత ప్యాటర్న్‌ను అంచనా వేస్తుంది.</p><Button asChild variant="white" className="mt-5 w-full"><a href="/te/appointment">అపాయింట్‌మెంట్</a></Button></div></aside></article><TeCTA/>
  </div>;
}

