export function TeLocationsIndex() {return <div lang="te"><TeHero badge="స్థానిక సేవలు" title="విజయవాడ మరియు సమీప ప్రాంతాల కోసం సైకియాట్రిక్ సంరక్షణ." description="క్లినిక్ సూర్యారావుపేటలో నక్కల రోడ్ సమీపంలో ఉంది. ప్రయాణానికి ముందు అపాయింట్‌మెంట్ మరియు లైవ్ దిశలను నిర్ధారించండి." current="ప్రాంతాలు"/><section className="container-page py-14 md:py-20"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{localPages.map(p=><a key={p.slug} href={`/te/locations/${p.slug}`} className="rounded-2xl border border-border bg-card p-5 shadow-card transition hover:-translate-y-1"><MapPin className="size-5 text-primary"/><h2 className="mt-4 text-lg font-extrabold">{localTe[p.slug]} సమీపంలో సైకియాట్రిస్ట్</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">సూర్యారావుపేటలో డా. పామర్తి కృష్ణ దాస్‌తో అపాయింట్‌మెంట్ మరియు ప్రయాణ సమాచారం.</p></a>)}</div></section><TeCTA/></div>}

export function TeLocationPage({slug}:{slug:string}){const p=localPages.find(x=>x.slug===slug);if(!p)return null;const area=localTe[slug]||p.name;return <div lang="te"><TeHero badge={`${area} నుంచి సంరక్షణ`} image={locationImage()} title={`${area} సమీపంలో సైకియాట్రిస్ట్`} description={`${area} నుంచి వచ్చే వ్యక్తులు మరియు కుటుంబాలు మూడ్, భయం, నిద్ర, వ్యసనం, పిల్లల ప్రవర్తన లేదా జ్ఞాపక సమస్యల కోసం సూర్యారావుపేట క్లినిక్‌లో కన్సల్టేషన్ కోరవచ్చు.`} current={area}><Button asChild><a href="/te/appointment"><CalendarDays/>అపాయింట్‌మెంట్</a></Button><Button asChild variant="outline"><a href={siteConfig.googleMapsUrl} target="_blank" rel="noreferrer"><MapPin/>లైవ్ దిశలు</a></Button></TeHero><section className="container-page py-16"><div className="grid gap-8 lg:grid-cols-2"><div><p className="eyebrow">ప్రయాణానికి ముందు</p><h2 className="section-title mt-5">సమయం నిర్ధారించి బయలుదేరండి.</h2><p className="mt-5 text-sm leading-8 text-muted-foreground">క్లినిక్: {siteConfig.address.line1}, {siteConfig.address.line2}, సూర్యారావుపేట, విజయవాడ – {siteConfig.address.postalCode}. ట్రాఫిక్ మారవచ్చు; స్థిర ప్రయాణ సమయాన్ని ఊహించకుండా Google Maps ఉపయోగించండి.</p><ul className="mt-7 grid gap-3 text-sm text-muted-foreground"><li>✓ కన్సల్టెంట్ సైకియాట్రిక్ అంచనా</li><li>✓ అవసరమైనప్పుడు మందుల సమీక్ష</li><li>✓ పిల్లలు, పెద్దలు మరియు వృద్ధుల సంరక్షణ</li><li>✓ కుటుంబ మార్గదర్శకం మరియు వ్యసన చికిత్స</li></ul></div><div className="overflow-hidden rounded-[1.8rem] border border-border bg-muted min-h-80"><iframe src={siteConfig.googleMapsEmbed} className="h-full min-h-80 w-full border-0" loading="lazy" title="కృష్ణ న్యూరో సైకియాట్రిక్ సెంటర్ మ్యాప్"/></div></div></section><TeCTA title={`${area} నుంచి అపాయింట్‌మెంట్‌ను ఒక కాల్‌తో ప్లాన్ చేయండి.`}/></div>}

export function TeAppointmentPage(){return <div lang="te"><TeHero badge="అపాయింట్‌మెంట్ అభ్యర్థన" title="ప్రారంభించేందుకు సరైన పదాలు అవసరం లేదు." description="అవసరమైన బుకింగ్ వివరాలు మాత్రమే ఇవ్వండి. క్లినిక్ అందుబాటు మరియు తదుపరి దశలను నిర్ధారిస్తుంది." current="అపాయింట్‌మెంట్"/><section className="container-page py-12 md:py-18"><div className="grid items-start gap-8 lg:grid-cols-[minmax(0,1fr)_19rem]"><TeluguAppointmentForm/><aside className="space-y-5 lg:sticky lg:top-28"><div className="rounded-[1.6rem] border border-border bg-card p-6"><h2 className="text-lg font-extrabold">నేరుగా సంప్రదించాలా?</h2><a href={`tel:${siteConfig.phones[0]}`} className="mt-5 flex items-center gap-3 rounded-xl border border-border p-3 text-sm font-bold"><Phone className="size-4 text-primary"/>{siteConfig.displayPhones[0]}</a></div><div className="rounded-[1.6rem] bg-muted/55 p-6 text-sm leading-7 text-muted-foreground"><strong className="text-foreground">సమయాలు:</strong><br/>సోమ–శని · ఉ. 9–రా. 9<br/>ఆదివారం సెలవు · ముందుగా నిర్ధారించండి</div></aside></div><div className="mt-8"><TeEmergencyStrip/></div></section></div>}

