export function TeGalleryPage(){return <div lang="te"><TeHero badge="క్లినిక్ ఆర్కైవ్" title="గ్యాలరీ: ఫోటోలు, వీడియోలు, అవగాహన మరియు సమాజ సేవ." description="ప్రజా మానసిక ఆరోగ్య విద్య, వీడియో ఇంటర్వ్యూలు, వృత్తిపరమైన సమావేశాలు, పత్రికా కథనాలు మరియు సమాజ అవుట్‌రీచ్‌కు ఎంపిక చేసిన రికార్డు." current="గ్యాలరీ" image={gallerySlides[6].src}/><section className="container-page py-14 md:py-20"><div className="mb-8 max-w-3xl"><p className="eyebrow">ఫోటో ఆర్కైవ్</p><h2 className="section-title mt-5">క్లినిక్ చిత్రాలు, పత్రికా విద్య మరియు సమాజ కార్యక్రమాలు.</h2></div><div className="mb-8 rounded-2xl bg-primary/6 p-5 text-sm leading-7 text-muted-foreground">మునుపటి, ప్లే/పాజ్ మరియు తదుపరి బటన్లు ఉపయోగించండి. ఫోన్‌లో స్వైప్ చేయవచ్చు. ఏ చిత్రానికైనా నేరుగా వెళ్లేందుకు థంబ్‌నెయిల్ ఎంచుకోండి. Reduced motion ఆన్‌లో ఉంటే ఆటోప్లే స్వయంగా ఆగుతుంది.</div><GallerySlideshow/><section className="mt-16 border-t border-border pt-14" aria-labelledby="te-video-gallery-heading"><div className="mb-8 max-w-3xl"><p className="eyebrow">వీడియో ఆర్కైవ్</p><h2 id="te-video-gallery-heading" className="section-title mt-5">వీడియో ఇంటర్వ్యూలు, ఆరోగ్య విద్య మరియు సమాజ కార్యక్రమాలు.</h2><p className="mt-5 text-sm leading-7 text-muted-foreground">క్లినిక్ అందించిన ఏడు YouTube వీడియోలను గ్యాలరీలోనే చూడండి. ప్రారంభ పేజీ వేగం మరియు గోప్యత కోసం మీరు ఎంచుకున్న తర్వాత మాత్రమే వీడియో లోడ్ అవుతుంది.</p></div><YouTubeVideoGallery language="te"/></section><div className="mt-12 rounded-2xl bg-muted/45 p-6"><h2 className="text-lg font-extrabold">అసలు Facebook సోర్స్‌లు</h2><div className="mt-4 grid gap-3 sm:grid-cols-2">{gallerySlides.map((slide,index)=><a key={slide.id} href={slide.photoUrl || slide.albumUrl} target="_blank" rel="noreferrer" className="flex items-center justify-between rounded-xl bg-card/70 p-3 text-sm font-bold transition hover:bg-card hover:text-primary"><span>{String(index+1).padStart(2,"0")} · {slide.titleTe}</span><ExternalLink className="size-3.5"/></a>)}</div></div></section></div>}

const standardPages: Record<string,{badge:string;title:string;description:string;sections:{title:string;body:string}[]}>={
  "about-doctor":{badge:"డాక్టర్ గురించి",title:"డా. పామర్తి కృష్ణ దాస్",description:"Krishna Neuro Psychiatric Centre, విజయవాడలో కన్సల్టెంట్ సైకియాట్రిస్ట్. ఈ పేజీ ధృవీకరించిన వృత్తిపరమైన మరియు కన్సల్టేషన్ సమాచారాన్ని మాత్రమే అందిస్తుంది.",sections:[{title:"ముందుగా అర్థం చేసుకోవటం",body:"లక్షణాలు సాధారణంగా ఒంటరిగా రావు. నిద్ర, శారీరక ఆరోగ్యం, మందులు, కుటుంబం, పని మరియు ఒత్తిడిని కలిపి పరిశీలించి పెద్ద నిర్ణయాలు తీసుకుంటారు."},{title:"ఆలోచించి మందులు",body:"మందులను పూర్తిగా నివారించటం లేదా ఆటోమేటిక్‌గా కొనసాగించటం లక్ష్యం కాదు. స్పష్టమైన క్లినికల్ అవసరం, లాభం, సైడ్ ఎఫెక్ట్స్ మరియు క్రమమైన సమీక్ష ఆధారంగా నిర్ణయం తీసుకుంటారు."},{title:"నిజ జీవితంలో కోలుకోవటం",body:"పురోగతి అంటే లక్షణాలు మాత్రమే తగ్గటం కాదు; నిద్ర, సంబంధాలు, చదువు, పని, స్వతంత్రత మరియు జీవన నాణ్యత మెరుగుపడటం కూడా."}]},
  treatments:{badge:"వ్యక్తిగత చికిత్స",title:"సరైన చికిత్స కలిసి తీసుకునే నిర్ణయం.",description:"అవగాహన, థెరపీ, ప్రాక్టికల్ సహాయం, కుటుంబ భాగస్వామ్యం, మందులు లేదా రిఫరల్—వ్యక్తి అవసరానికి అనుగుణంగా.",sections:[{title:"పూర్తి అంచనా",body:"లక్షణాల కాలక్రమం, ఆరోగ్యం, మందులు, నిద్ర, పనితీరు మరియు భద్రతను పరిశీలిస్తారు."},{title:"సైకలాజికల్ మరియు ప్రాక్టికల్ సంరక్షణ",body:"కౌన్సెలింగ్, CBT ఆధారిత నైపుణ్యాలు, దినచర్య, నిద్ర, కమ్యూనికేషన్ మరియు కుటుంబ సహాయం ప్రణాళికలో భాగం కావచ్చు."},{title:"తక్కువ ప్రభావవంతమైన చికిత్స భారం",body:"అవసరమైనప్పుడు సరిపడా ప్రభావం ఇచ్చే, అంగీకారయోగ్యమైన సైడ్ ఎఫెక్ట్స్ ఉన్న చికిత్సను లక్ష్యంగా పెడతారు. చాలా తక్కువ చికిత్స కూడా ప్రమాదకరం కావచ్చు."}]},
  "patient-journey":{badge:"ఏమి ఆశించాలి",title:"ఒక్కో స్పష్టమైన అడుగుతో రోగి ప్రయాణం.",description:"బుకింగ్ నుంచి దీర్ఘకాల ఆరోగ్యం వరకు ప్రతి దశ ఎందుకో తెలుసుకోండి.",sections:teJourney.map((x,i)=>({title:`దశ ${i+1}: ${x}`,body:["క్లినిక్‌కు కాల్, WhatsApp లేదా చిన్న ఫారమ్ ద్వారా సమయం కోరండి.","మీ మాటల్లో సమస్యను వివరించండి; కావాలంటే నమ్మకమైన కుటుంబ సభ్యుడిని తీసుకురండి.","లక్షణాలు, ఆరోగ్యం, మందులు, నిద్ర, సందర్భం మరియు భద్రతను పరిశీలిస్తారు.","ఏది సరిపోతుంది, ఏది ఇంకా స్పష్టం కాదు, ఏ పరీక్ష అవసరమో వివరిస్తారు.","ప్రాక్టికల్, సైకలాజికల్ మరియు వైద్య ఎంపికలను కలిసి ఎంచుకుంటారు.","పురోగతి, సైడ్ ఎఫెక్ట్స్ మరియు మారుతున్న లక్ష్యాలను సమీక్షిస్తారు.","స్వతంత్రత, హెచ్చరిక సంకేతాలు మరియు అర్థవంతమైన రోజువారీ జీవితాన్ని నిర్మిస్తారు."][i]}))},
  resources:{badge:"మానసిక ఆరోగ్య వనరులు",title:"మంచి సమాచారం భయాన్ని తగ్గించాలి.",description:"లక్షణాలు గమనించడం, కుటుంబానికి సహాయం చేయడం మరియు సరైన సమయంలో సంరక్షణ పొందేందుకు తెలుగు వనరులు.",sections:[{title:"లక్షణాలను అర్థం చేసుకోండి",body:"మూడ్, భయం, సైకోసిస్, వ్యసనం, జ్ఞాపకం మరియు పిల్లల సమస్యలపై సులభమైన గైడ్లను conditions విభాగంలో చదవండి."},{title:"మొదటి అపాయింట్‌మెంట్‌కు సిద్ధం",body:"ప్రస్తుత మందులు, ముఖ్యమైన రిపోర్టులు, చిన్న కాలక్రమం మరియు మీ ప్రశ్నలను తీసుకురండి. అత్యవసర సంరక్షణను పత్రాల కోసం ఆలస్యం చేయవద్దు."},{title:"ప్రభుత్వ సహాయం",body:"తక్షణ ప్రమాదంలో 112. ఉచిత 24/7 జాతీయ టెలి-మెంటల్ హెల్త్ సహాయం Tele-MANAS 14416."}]},
  faqs:{badge:"తరచుగా అడిగే ప్రశ్నలు",title:"సైకియాట్రిక్ కన్సల్టేషన్ గురించి తరచుగా అడిగే ప్రశ్నలు",description:"అపాయింట్‌మెంట్, మందులు, గోప్యత, కుటుంబం మరియు అత్యవసర సహాయం గురించి సమాధానాలు.",sections:[]},
  contact:{badge:"సంప్రదింపు మరియు దిశలు",title:"మీకు సులభమైన విధంగా క్లినిక్‌ను సంప్రదించండి.",description:"అపాయింట్‌మెంట్ కోసం కాల్ లేదా WhatsApp చేయండి; సూర్యారావుపేటకు లైవ్ దిశలను తెరవండి.",sections:[{title:"వాయిస్ కాల్స్",body:`${siteConfig.displayPhones[0]}`},{title:"WhatsApp మరియు అపాయింట్‌మెంట్లు",body:`${siteConfig.whatsappDisplay}`},{title:"చిరునామా",body:`${siteConfig.address.line1}, ${siteConfig.address.line2}, సూర్యారావుపేట, విజయవాడ – ${siteConfig.address.postalCode}`},{title:"సమయాలు",body:"సోమవారం–శనివారం · ఉదయం 9–రాత్రి 9. ఆదివారం సెలవు. ప్రయాణానికి ముందు కాల్ చేసి నిర్ధారించండి."}]},
  "clinic-vijayawada":{badge:"క్లినిక్ సందర్శన",title:"విజయవాడలో కృష్ణ న్యూరో సైకియాట్రిక్ సెంటర్‌ను సందర్శించండి.",description:"సూర్యారావుపేట క్లినిక్ చిరునామా, సమయాలు, ప్రయాణ ప్రణాళిక మరియు అపాయింట్‌మెంట్ ఎంపికలు.",sections:[{title:"క్లినిక్ మరియు డాక్టర్",body:`${siteConfig.name}. ${siteConfig.doctor}, ${siteConfig.credentials}, ${siteConfig.role}.`},{title:"ధృవీకరించిన చిరునామా",body:`${siteConfig.address.line1}, ${siteConfig.address.line2}, ${siteConfig.address.locality}, ${siteConfig.address.city} – ${siteConfig.address.postalCode}.`},{title:"క్లినిక్ సమయాలు",body:`${siteConfig.hours.summary}. ${siteConfig.hours.closed}. ప్రయాణానికి ముందు డాక్టర్ అందుబాటును నిర్ధారించండి.`},{title:"సందర్శనకు సిద్ధం కావడం",body:"ప్రస్తుత మందుల జాబితా, ఉపయోగకరమైన రిపోర్టులు మరియు గమనించిన మార్పుల చిన్న కాలక్రమం తీసుకురావచ్చు. పత్రాల కోసం అత్యవసర సహాయాన్ని ఆలస్యం చేయవద్దు."},{title:"యాక్సెస్ సమాచారం",body:"పార్కింగ్ మరియు స్టెప్-ఫ్రీ యాక్సెస్ వివరాలు ప్రచురణ కోసం ఇంకా ధృవీకరించబడలేదు. ప్రత్యేక సహాయం అవసరమైతే ప్రయాణానికి ముందు క్లినిక్‌కు కాల్ చేయండి."}]},
  "privacy-policy":{badge:"గోప్యత",title:"గోప్యతా విధానం",description:"వెబ్‌సైట్ ఏ వివరాలను ఎందుకు ఉపయోగిస్తుంది, WhatsApp మరియు ఆన్‌లైన్ కమ్యూనికేషన్ పరిమితులు ఏమిటో స్పష్టమైన వివరణ.",sections:[{title:"మీరు ఇచ్చే సమాచారం",body:"అపాయింట్‌మెంట్ ఫారమ్ పేరు, ఫోన్, కన్సల్టేషన్ విధానం, కోరిన తేదీ, సమయం మరియు సమాధాన విధానం మాత్రమే అడుగుతుంది. లక్షణాలు, నిర్ధారణ, వయస్సు, మందులు లేదా వైద్య రికార్డులు అడగదు. అత్యవసర మెసేజ్‌లు పంపవద్దు."},{title:"డెలివరీ",body:"సురక్షిత వెబ్‌హుక్ ఉన్నప్పుడు వివరాలు క్లినిక్ వ్యవస్థకు పంపబడవచ్చు. లేకపోతే WhatsApp మెసేజ్ సిద్ధమవుతుంది; మీరు Send నొక్కే వరకు పంపబడదు."},{title:"వాడుక మరియు గోప్యత",body:"అభ్యర్థనకు స్పందించడం, అపాయింట్‌మెంట్ మరియు చట్టబద్ధ/క్లినికల్ బాధ్యతల కోసం సమాచారం వాడబడుతుంది. విక్రయించబడదు. తీవ్రమైన భద్రతా ప్రమాదం లేదా చట్టబద్ధ బాధ్యతలో గోప్యతకు పరిమితులు ఉండవచ్చు."},{title:"అనలిటిక్స్ మరియు బాహ్య సేవలు",body:"మీ సమ్మతి తర్వాత మాత్రమే ఐచ్ఛిక అనలిటిక్స్ లోడ్ అవుతాయి. గ్యాలరీలో Play నొక్కిన తర్వాత మాత్రమే YouTube privacy-enhanced ప్లేయర్ లోడ్ అవుతుంది. WhatsApp, Google Maps, YouTube మరియు ఇతర బాహ్య సేవలకు వారి స్వంత గోప్యతా విధానాలు ఉంటాయి."},{title:"సంప్రదింపు",body:`గోప్యతా ప్రశ్నలకు ${siteConfig.email}కు ఇమెయిల్ లేదా ${siteConfig.displayPhones[0]}కు కాల్ చేయండి. ఎమర్జెన్సీకి 112.`}]},
  "medical-disclaimer":{badge:"ముఖ్యమైన భద్రతా సమాచారం",title:"వైద్య సమాచార పరిమితులు",description:"ఈ వెబ్‌సైట్ సాధారణ అవగాహన కోసం మాత్రమే; వ్యక్తిగత వైద్య లేదా సైకియాట్రిక్ అంచనాను భర్తీ చేయదు.",sections:[{title:"వ్యక్తిగత నిర్ధారణ కాదు",body:"ఆన్‌లైన్ సమాచారం మీ పూర్తి చరిత్ర, శారీరక ఆరోగ్యం, మందులు, వయస్సు, గర్భధారణ, పదార్థాల వాడకం లేదా భద్రతను అంచనా వేయలదు. పేజీ చదవడం వల్ల డాక్టర్–రోగి సంబంధం ఏర్పడదు."},{title:"మందుల భద్రత",body:"ఈ వెబ్‌సైట్ ఆధారంగా ప్రిస్క్రిప్షన్ మందులను ప్రారంభించవద్దు, పంచుకోవద్దు, తగ్గించవద్దు లేదా అకస్మాత్తుగా ఆపవద్దు. మందుల మార్పులను ప్రిస్క్రైబ్ చేసిన వైద్యుడితో చర్చించండి."},{title:"ఎమర్జెన్సీ సేవ కాదు",body:"ఆత్మహత్య ప్రయత్నం లేదా ప్రణాళిక, ఓవర్‌డోస్, ఫిట్స్, తీవ్రమైన గందరగోళం, హింస లేదా భద్రంగా ఉండలేని పరిస్థితిలో 112కు కాల్ చేయండి లేదా సమీప ఎమర్జెన్సీ విభాగానికి వెళ్లండి. Tele-MANAS: 14416."},{title:"ఫలితాలు మారుతాయి",body:"ఏ పేజీ కూడా నయం, కోలుకునే సమయం, మందుల స్పందన లేదా చికిత్స ఫలితాన్ని హామీ ఇవ్వదు. వ్యక్తిగత అంచనా ఆధారంగా సిఫార్సులు మారవచ్చు."}]},
  terms:{badge:"చట్టపరమైన సమాచారం",title:"వెబ్‌సైట్ వినియోగ నిబంధనలు",description:"ఈ వెబ్‌సైట్ ఏమి చేయగలదు, ఏమి చేయలేదో అర్థం చేసుకోండి.",sections:[{title:"విద్యా సమాచారం మాత్రమే",body:"వెబ్‌సైట్ సాధారణ మానసిక ఆరోగ్య సమాచారాన్ని ఇస్తుంది. వ్యక్తిగత నిర్ధారణ, ప్రిస్క్రిప్షన్ లేదా వైద్య సంప్రదింపును భర్తీ చేయదు."},{title:"ఎమర్జెన్సీ కాదు",body:"వెబ్‌సైట్ ఫారమ్‌లు ఎమర్జెన్సీ సేవలు కావు. తక్షణ ప్రమాదంలో 112 లేదా సమీప ఎమర్జెన్సీ విభాగం; Tele-MANAS 14416."},{title:"అపాయింట్‌మెంట్ మరియు ఫలితాలు",body:"అభ్యర్థన నిర్దిష్ట సమయం, మందు లేదా ఫలితాన్ని హామీ ఇవ్వదు. క్లినిక్ సమాధానం తర్వాతే అపాయింట్‌మెంట్ నిర్ధారితం. చికిత్స ఫలితాలు వ్యక్తికి వ్యక్తి మారుతాయి."},{title:"మందుల భద్రత",body:"వెబ్‌సైట్ ఆధారంగా మందులను ప్రారంభించవద్దు, పంచుకోవద్దు లేదా అకస్మాత్తుగా ఆపవద్దు."}]},
  emergency:{badge:"తక్షణ భద్రత",title:"ఎవరైనా భద్రంగా ఉండకపోతే ఇప్పుడే చర్య తీసుకోండి.",description:"ఈ క్లినిక్ వెబ్‌సైట్ ఎమర్జెన్సీ సేవ కాదు. ప్రమాదం ఉన్నప్పుడు సాధారణ అపాయింట్‌మెంట్ కోసం వేచి ఉండవద్దు.",sections:[{title:"112కు కాల్ చేయాల్సిన పరిస్థితులు",body:"ఆత్మహత్య ప్రయత్నం లేదా ప్రణాళిక, ఓవర్‌డోస్, ఫిట్స్, తీవ్రమైన హింస, అకస్మాత్తు గందరగోళం లేదా భద్రంగా ఉంచలేని పరిస్థితి."},{title:"సహాయం వచ్చే వరకు",body:"సురక్షితమైతే వ్యక్తితో ఉండండి. ఆత్మహత్య ప్రణాళిక గురించి నేరుగా అడగండి. ప్రమాదకర వస్తువులకు ప్రాప్యతను తగ్గించండి. ప్రశాంతంగా, చిన్న వాక్యాలతో మాట్లాడండి."},{title:"Tele-MANAS",body:"భారతదేశంలో ఉచిత 24/7 టెలి-మెంటల్ హెల్త్ సహాయం: 14416 లేదా 1800-89-14416."}]},
  "psychiatrist-in-vijayawada":{badge:"విజయవాడ కన్సల్టెంట్ సైకియాట్రిస్ట్",title:"గౌరవం మరియు ఆధారాలతో కూడిన విజయవాడ సైకియాట్రిక్ సంరక్షణ.",description:"సూర్యారావుపేటలో Krishna Neuro Psychiatric Centre వద్ద డా. పామర్తి కృష్ణ దాస్, MBBS, MD (Psychiatry).",sections:[{title:"సైకియాట్రిస్ట్ ఎందుకు?",body:"సైకియాట్రిస్ట్ మానసిక లక్షణాలు, శారీరక కారణాలు, మందుల ప్రభావం మరియు భద్రతను అంచనా వేయగల వైద్యుడు. కన్సల్టేషన్ అంటే తప్పనిసరిగా మందులు కాదు."},{title:"సేవల పరిధి",body:"డిప్రెషన్, ఆందోళన, OCD, బైపోలార్, సైకోసిస్, నిద్ర, వ్యసనం, పిల్లలు, మహిళలు మరియు వృద్ధుల మానసిక ఆరోగ్య సమస్యలు."},{title:"క్లినిక్",body:`${siteConfig.address.line1}, సూర్యారావుపేట, విజయవాడ – ${siteConfig.address.postalCode}. కాల్: ${siteConfig.displayPhones[0]}.`}]},
};

export function TeStandardPage({page}:{page:string}){const data=standardPages[page];if(!data)return null;if(page==="faqs")return <div lang="te"><TeHero badge={data.badge} image={pageImage(page)} title={data.title} description={data.description} current="ప్రశ్నలు"/><section className="container-page py-14 md:py-20"><div className="rounded-[1.8rem] border border-border bg-card px-6 shadow-card"><FAQList faqs={teFaqs}/></div></section><TeCTA/></div>;return <div lang="te"><TeHero badge={data.badge} image={pageImage(page)} title={data.title} description={data.description} current={data.title}>{["about-doctor","treatments","patient-journey","contact","clinic-vijayawada","psychiatrist-in-vijayawada"].includes(page)&&<Button asChild><a href="/te/appointment"><CalendarDays/>అపాయింట్‌మెంట్ కోరండి</a></Button>}</TeHero><section className="container-page py-14 md:py-20"><div className="grid gap-5 md:grid-cols-2">{data.sections.map((s,i)=><Card key={`${s.title}-${i}`} className="p-7"><span className="text-xs font-black text-primary">0{i+1}</span><h2 className="mt-3 text-2xl font-extrabold tracking-[-0.025em]">{s.title}</h2><p className="mt-4 whitespace-pre-line text-sm leading-8 text-muted-foreground">{s.body}</p></Card>)}</div>{["contact","clinic-vijayawada"].includes(page)&&<div className="mt-10 overflow-hidden rounded-[1.8rem] border border-border min-h-96"><iframe src={siteConfig.googleMapsEmbed} className="h-96 w-full border-0" loading="lazy" title="క్లినిక్ మ్యాప్"/></div>}{page==="emergency"&&<div className="mt-8"><TeEmergencyStrip/></div>}</section>{!["privacy-policy","medical-disclaimer","terms","emergency"].includes(page)&&<TeCTA/>}</div>}
